from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
urls=set()
for p in r.pages:
 for ref in p.get('/Annots', []):
  a=ref.get_object().get('/A')
  if a and a.get('/URI'):
   urls.add(str(a['/URI']))
print('Repository and artifact links:')
for u in sorted(urls):
 if any(s in u.lower() for s in ['github', 'zenodo', 'huggingface', 'osf.io', 'figshare', 'supplement', 'dataset']):
  print(u)
print('Embedded files:',list(r.attachments))
